class Solution {
public:
    int minZeroArray(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        int m = queries.size();

        auto can = [&](int k) -> bool {
            vector<long long> diff(n + 1, 0);
            for (int i = 0; i < k; i++) {
                int l = queries[i][0], r = queries[i][1], v = queries[i][2];
                diff[l] += v;
                diff[r + 1] -= v;
            }
            long long cur = 0;
            for (int i = 0; i < n; i++) {
                cur += diff[i];
                if (cur < (long long)nums[i]) return false;
            }
            return true;
        };

        if (!can(m)) return -1;

        int lo = 0, hi = m;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (can(mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};
